import java.util.Scanner;

public class Main {
    static double Tabs(double n) {
        return n >= 0 ? n : -n;
    }

    static int solveIt(int x, int y, int b) {
        double target = (double) x / y;
        int lb = 0, ub = 1000000;
        for (int i = 0; i < 25; i++) {
            int a = (lb + ub) / 2;
            if ((double) a / b < target)
                lb = a;
            else
                ub = a;
        }
        int res = 0;
        double diff = Double.MAX_VALUE;
        for (int a = lb - 10; a <= ub + 10; a++) {
            double d = Tabs((double) a / b - target);
            if (d < diff) {
                diff = d;
                res = a;
            }
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int x = sc.nextInt();
        int y = sc.nextInt();
        int n = sc.nextInt();
        int ans1 = 0, ans2 = 1;
        double best_diff = Double.MAX_VALUE;
        for (int b = 1; b <= n; b++) {
            int a = solveIt(x, y, b);
            double d = Tabs((double) a / b - (double) x / y);
            if (d < best_diff) {
                best_diff = d;
                ans1 = a;
                ans2 = b;
            }
        }
        System.out.println(ans1 + "/" + ans2);
        sc.close();
    }
}
